examples.code:
New-OfficePdf -Path .\Status.pdf {
    PdfHeading 'Weekly status'
    PdfParagraph 'All production services are healthy.'
}

$services = @(
    [pscustomobject]@{ Service = 'Identity'; Owner = 'Platform'; Availability = 99.98; Incidents = 0; Status = 'Healthy' }
    [pscustomobject]@{ Service = 'Mail'; Owner = 'Messaging'; Availability = 99.71; Incidents = 2; Status = 'Watch' }
    [pscustomobject]@{ Service = 'File shares'; Owner = 'Infrastructure'; Availability = 99.95; Incidents = 1; Status = 'Healthy' }
    [pscustomobject]@{ Service = 'VPN'; Owner = 'Network'; Availability = 98.90; Incidents = 4; Status = 'At risk' }
)
$params = @{
    Path                      = '.\Reports\Service-Review-2026-10.pdf'
    Theme                     = 'Boardroom'
    CreateOutlineFromHeadings = $true
    Force                     = $true
    Show                      = $true
}
New-OfficePdf @params {
    PdfMetadata -Title 'Service review - October 2026' -Author 'IT Operations' -Subject 'Monthly service review'
    PdfPageSetup -PageSize A4 -Margin 2cm
    PdfHeader 'Service review - October 2026' -Alignment Right
    PdfFooter {
        PdfText 'Internal - page '
        PdfPageNumber -IncludeTotal
    }
    PdfHeading 'Service review'
    PdfParagraph {
        PdfText 'Overall status: '
        PdfText 'On track' -Bold -Color Success
    }
    PdfPanel 'VPN availability fell below target after the 14 October ISP outage.'
    PdfHeading 'Availability' -Level 2
    PdfTable -InputObject $services
    PdfChart -InputObject $services -Category Service -Value Incidents -Type Column -Title 'Incidents by service'
}

$sales = @(
    [pscustomobject]@{ Region = 'North'; Q1 = 1.42; Q2 = 1.55; Q3 = 1.71 }
    [pscustomobject]@{ Region = 'South'; Q1 = 0.98; Q2 = 1.04; Q3 = 1.12 }
    [pscustomobject]@{ Region = 'East'; Q1 = 1.21; Q2 = 1.18; Q3 = 1.36 }
    [pscustomobject]@{ Region = 'West'; Q1 = 1.65; Q2 = 1.79; Q3 = 1.88 }
)
$pdf = New-OfficePdf -Theme Modern
foreach ($row in $sales) {
    Add-OfficePdfHeading -Document $pdf -Text "$($row.Region) region"
    Add-OfficePdfParagraph -Document $pdf -Text "Q3 revenue: $($row.Q3) million USD."
}
Save-OfficePdf -Document $pdf -Path .\Reports\Q3-Regions.pdf

Open-OfficePdf -Path .\Reports\Q3-Board-Pack.pdf -OutputPath .\Reports\Q3-Board-Pack-Final.pdf {
    Remove-OfficePdfPage -Page 2
    PdfMetadata -Title 'Q3 board pack' -Author 'Finance' -Subject 'Quarterly results'
    Add-OfficePdfStamp -Text 'BOARD CONFIDENTIAL' -Size 36 -Rotation 30 -Opacity 0.15 -Behind
}

$password = Read-Host -Prompt 'PDF password' -AsSecureString
Open-OfficePdf -Path .\HR\Offer-Letter.pdf -Password $password -OutputPath .\HR\Offer-Letter-Completed.pdf {
    Set-OfficePdfFormField -Value @{ CandidateName = 'Grace Hopper'; StartDate = '2026-11-02' }
}

$pdf = Open-OfficePdf -Path .\Requests\Access-Request-4711.pdf
try {
    Get-OfficePdfFormField -Document $pdf |
        Select-Object Name, Value |
        Export-Csv -Path .\Requests\Access-Request-4711.csv -NoTypeInformation
} finally {
    Close-OfficePdf -Document $pdf
}

New-OfficePdf -Path .\Runbooks\SQL-Failover.pdf -CreateOutlineFromHeadings {
    PdfHeading 'SQL failover runbook'
    PdfParagraph {
        PdfText 'If the secondary does not come online in 10 minutes, follow '
        PdfText 'Escalation' -LinkBookmark 'escalation'
        PdfText '.'
    }
    PdfHeading 'Preparation' -Level 2
    PdfParagraph 'Confirm the availability group is synchronized.'
    PdfHeading 'Escalation' -Level 2 -Bookmark 'escalation'
    PdfParagraph 'Page the on-call DBA through the incident bridge.'
}

New-OfficePdf -Path .\Notice.pdf {
    PdfParagraph 'The data center maintenance window starts Saturday at 22:00 UTC.'
}

New-OfficePdf -Path .\Reports\Change-CHG0042.pdf {
    PdfHeading 'Change CHG0042'
    PdfParagraph {
        PdfText 'Risk: '
        PdfText 'Low' -Bold -Color Success
        PdfText '. Rollback tested on '
        PdfText '18 October' -Italic
        PdfText '. Details in the '
        PdfText 'change record' -Link 'https://servicedesk.example.com/change/CHG0042'
        PdfText '.'
    }
}

New-OfficePdf -Path .\Reports\Release-Notes-4.2.pdf {
    PdfHeading 'Release 4.2'
    PdfParagraph {
        PdfText 'Support ends on '
        PdfText '30 June 2026' -Strikethrough
        PdfText ' 31 December 2026' -Bold
        PdfText '. See the '
        PdfText 'lifecycle policy' -Link 'https://example.com/lifecycle'
        PdfText ' for details.'
    }
}

New-OfficePdf -Path .\Actions.pdf {
    PdfList {
        PdfListItem 'Confirm the service owner'
        PdfListItem 'Publish the summary'
        PdfListItem 'Schedule the review'
    }
}

$steps = 'Drain the node', 'Apply the patch', 'Reboot', 'Return the node to the pool'
New-OfficePdf -Path .\Runbooks\Patch-Node.pdf {
    PdfHeading 'Patch a cluster node'
    PdfList -Numbered {
        foreach ($step in $steps) {
            PdfListItem $step
        }
        PdfListItem {
            PdfText 'Confirm '
            PdfText 'Ready' -Bold
            PdfText ' in the cluster console'
        }
    }
}

New-OfficePdf -Path .\Reports\Patch-Window.pdf {
    PdfHeading 'Patch window steps'
    PdfList -Numbered -Items 'Drain node 1', 'Patch and reboot', 'Return node to the pool', 'Repeat for node 2'
}

New-OfficePdf -Path .\Checklist.pdf {
    PdfList {
        PdfListItem 'Backups verified'
        PdfListItem 'Monitoring silenced'
    }
}

$tickets = @(
    [pscustomobject]@{ Id = 'INC-1042'; Title = 'VPN drops every 30 minutes'; Priority = 'High' }
    [pscustomobject]@{ Id = 'INC-1051'; Title = 'Shared mailbox not syncing'; Priority = 'Medium' }
)
New-OfficePdf -Path .\Reports\Open-Tickets.pdf {
    PdfHeading 'Open tickets'
    PdfList {
        foreach ($ticket in $tickets) {
            PdfListItem {
                PdfText "$($ticket.Id) " -Bold
                PdfText "$($ticket.Title) - "
                PdfText $ticket.Priority -Color Warning
            }
        }
    }
}

$services = @(
    [pscustomobject]@{ Service = 'Identity'; Owner = 'Platform'; Availability = 99.98; Incidents = 0; Status = 'Healthy' }
    [pscustomobject]@{ Service = 'Mail'; Owner = 'Messaging'; Availability = 99.71; Incidents = 2; Status = 'Watch' }
    [pscustomobject]@{ Service = 'File shares'; Owner = 'Infrastructure'; Availability = 99.95; Incidents = 1; Status = 'Healthy' }
    [pscustomobject]@{ Service = 'VPN'; Owner = 'Network'; Availability = 98.90; Incidents = 4; Status = 'At risk' }
)
New-OfficePdf -Path .\Services.pdf {
    PdfTable -InputObject $services
}

$tickets = Import-Csv -Path .\Data\Tickets-October.csv
New-OfficePdf -Path .\Reports\Tickets-October.pdf {
    PdfHeading 'Tickets closed in October'
    $tickets | PdfTable -Property Id, Title, Owner, ClosedOn -Header 'Ticket', 'Summary', 'Owner', 'Closed' -Caption 'Source: service desk export' -RepeatHeaderRowCount 1
}

New-OfficePdf -Path .\Reports\DR-Targets.pdf {
    PdfHeading 'Recovery targets'
    $rows = @(
        @('System', 'Owner', 'RPO'),
        @(PdfTableCell 'Tier 1' -ColumnSpan 3 -Bold),
        @('ERP', 'Finance IT', '15 min'),
        @('Payroll', 'HR IT', '1 h')
    )
    PdfTable -InputObject $rows
}

$format = @{ Revenue = 'Currency'; Margin = @{ Format = 'Percent'; Decimals = 1 }; Closed = 'Date' }
New-OfficePdf -Path .\Reports\Deals.pdf {
    PdfHeading 'Closed deals'
    PdfTable -InputObject (Import-Csv -Path .\Data\Deals.csv) -ColumnFormat $format
}

$controls = 'Backups tested', 'Access reviewed', 'Patching current'
New-OfficePdf -Path .\Audit\Q4-Controls.pdf {
    PdfHeading 'Q4 control sign-off'
    $rows = @(, @('Control', 'Done', 'Reviewer'))
    foreach ($control in $controls) {
        $id = $control -replace '\W', ''
        $done = PdfTableCell { PdfFormField "$id-Done" -Type CheckBox }
        $reviewer = PdfTableCell { PdfFormField "$id-Reviewer" -Type Choice -Option 'Unassigned', 'Ada', 'Grace' -Value 'Unassigned' }
        $rows += , @($control, $done, $reviewer)
    }
    PdfTable -InputObject $rows
}

$sales = @(
    [pscustomobject]@{ Region = 'North'; Q1 = 1.42; Q2 = 1.55; Q3 = 1.71 }
    [pscustomobject]@{ Region = 'South'; Q1 = 0.98; Q2 = 1.04; Q3 = 1.12 }
    [pscustomobject]@{ Region = 'East'; Q1 = 1.21; Q2 = 1.18; Q3 = 1.36 }
    [pscustomobject]@{ Region = 'West'; Q1 = 1.65; Q2 = 1.79; Q3 = 1.88 }
)
New-OfficePdf -Path .\Sales.pdf {
    PdfChart -InputObject $sales -Category Region -Value Q3 -Title 'Q3 revenue by region (USD m)'
}

$sales = @(
    [pscustomobject]@{ Region = 'North'; Q1 = 1.42; Q2 = 1.55; Q3 = 1.71 }
    [pscustomobject]@{ Region = 'South'; Q1 = 0.98; Q2 = 1.04; Q3 = 1.12 }
    [pscustomobject]@{ Region = 'East'; Q1 = 1.21; Q2 = 1.18; Q3 = 1.36 }
    [pscustomobject]@{ Region = 'West'; Q1 = 1.65; Q2 = 1.79; Q3 = 1.88 }
)
New-OfficePdf -Path .\Reports\Q3-Sales.pdf -Theme Boardroom {
    PdfHeading 'Revenue by region'
    PdfTable -InputObject $sales
    PdfChart -InputObject $sales -Category Region -Value Q1, Q2, Q3 -Type Line -Title 'Quarterly trend (USD m)' -Height 7cm -AlternativeText 'Revenue rises in every region except East in Q2.'
}

New-OfficePdf -Path .\Reports\Portal-Launch.pdf {
    PdfHeader {
        PdfImage .\Branding\Logo.png -Height 1cm
    }
    PdfHeading 'Customer portal launch'
    PdfImage .\Images\Portal-Home.png -Width 14cm -Alignment Center -AlternativeText 'Portal home page with the new navigation bar'
}

$svg = Get-Content -Path .\Images\Org-Chart.svg -Raw
$visual = ConvertTo-OfficeVisual -InputObject $svg -AlternativeText 'Organization chart'
New-OfficePdf -Path .\Reports\Org-Chart.pdf {
    PdfHeading 'Organization'
    PdfImage -InputObject $visual -Width 16cm -Alignment Center
}

New-OfficePdf -Path .\Summary.pdf {
    PdfPanel 'No critical incidents were recorded this month.'
}

New-OfficePdf -Path .\Reports\Mail-Migration-Decision.pdf {
    PdfHeading 'Mail migration'
    PdfPanel {
        PdfText 'Decision: ' -Bold
        PdfText 'migrate the remaining 1,200 mailboxes in two waves. Owner: Messaging team.'
    }
    PdfParagraph 'Wave 1 starts on 3 November; wave 2 follows after a one-week review.'
}

New-OfficePdf -Path .\TwoColumns.pdf {
    PdfRow {
        PdfColumn { PdfParagraph 'Left column' }
        PdfColumn { PdfParagraph 'Right column' }
    }
}

$services = @(
    [pscustomobject]@{ Service = 'Identity'; Owner = 'Platform'; Availability = 99.98; Incidents = 0; Status = 'Healthy' }
    [pscustomobject]@{ Service = 'Mail'; Owner = 'Messaging'; Availability = 99.71; Incidents = 2; Status = 'Watch' }
    [pscustomobject]@{ Service = 'File shares'; Owner = 'Infrastructure'; Availability = 99.95; Incidents = 1; Status = 'Healthy' }
    [pscustomobject]@{ Service = 'VPN'; Owner = 'Network'; Availability = 98.90; Incidents = 4; Status = 'At risk' }
)
New-OfficePdf -Path .\Reports\Ops-Dashboard.pdf {
    PdfHeading 'Operations dashboard'
    PdfRow -Gap 12pt -ColumnSeparatorColor TextMuted -KeepWithNext {
        PdfColumn {
            PdfHeading '99.6%' -Level 2
            PdfParagraph 'Average availability'
        }
        PdfColumn {
            PdfHeading '7' -Level 2
            PdfParagraph 'Incidents'
        }
        PdfColumn {
            PdfHeading '1' -Level 2 -Color Danger
            PdfParagraph 'Service at risk'
        }
    }
    PdfTable -InputObject $services
}

New-OfficePdf -Path .\Columns.pdf {
    PdfRow {
        PdfColumn { PdfHeading 'Signals' -Level 2 }
        PdfColumn { PdfPanel 'All checks passed.' }
    }
}

New-OfficePdf -Path .\Reports\Incident-INC-1042.pdf {
    PdfHeading 'Incident INC-1042'
    PdfRow -Gap 18pt {
        PdfColumn -Weight 30 {
            PdfHeading 'Facts' -Level 3
            PdfList {
                PdfListItem 'Severity 2'
                PdfListItem 'Duration 47 minutes'
                PdfListItem 'Owner: Network'
            }
        }
        PdfColumn -Weight 70 {
            PdfHeading 'Timeline' -Level 3
            PdfParagraph 'At 09:12 UTC the primary ISP link flapped; traffic failed over at 09:15.'
            PdfParagraph 'The link was restored at 09:59 after the carrier replaced a line card.'
        }
    }
}

$tickets = Import-Csv -Path .\Data\Tickets-By-Team.csv
New-OfficePdf -Path .\Reports\Service-Desk.pdf {
    PdfRow -Gap 12pt {
        PdfColumn -Width 4cm {
            PdfImage -Path .\Branding\Logo.png -Width 3.5cm
        }
        PdfColumn {
            PdfChart -InputObject $tickets -Category Team -Value Open, Closed -Type Column -Title 'Tickets by team'
        }
    }
}

New-OfficePdf -Path .\Memo.pdf {
    PdfParagraph 'Executive summary'
    PdfHorizontalRule
    PdfParagraph 'Details follow.'
}

New-OfficePdf -Path .\Reports\Change-Approval.pdf {
    PdfHeading 'Change approval'
    PdfParagraph 'The change board approved CHG0042 for the 8 November window.'
    PdfHorizontalRule -Thickness 1.5pt -Color Accent1 -SpacingBefore 24pt -SpacingAfter 6pt
    PdfParagraph 'Approved by: Change advisory board'
}

New-OfficePdf -Path .\Spaced.pdf {
    PdfParagraph 'First block'
    PdfSpacer 18pt
    PdfParagraph 'Second block'
}

$sales = @(
    [pscustomobject]@{ Region = 'North'; Q1 = 1.42; Q2 = 1.55; Q3 = 1.71 }
    [pscustomobject]@{ Region = 'South'; Q1 = 0.98; Q2 = 1.04; Q3 = 1.12 }
    [pscustomobject]@{ Region = 'East'; Q1 = 1.21; Q2 = 1.18; Q3 = 1.36 }
    [pscustomobject]@{ Region = 'West'; Q1 = 1.65; Q2 = 1.79; Q3 = 1.88 }
)
New-OfficePdf -Path .\Reports\Regional-Sales.pdf {
    for ($i = 0; $i -lt $sales.Count; $i++) {
        PdfHeading "$($sales[$i].Region) region"
        PdfTable -InputObject $sales[$i]
        if ($i -lt $sales.Count - 1) {
            PdfPageBreak
        }
    }
}

$sections = 'Scope', 'Findings', 'Recommendations'
New-OfficePdf -Path .\Audit\Security-Audit.pdf {
    PdfHeading 'Security audit 2026'
    PdfList {
        foreach ($section in $sections) {
            PdfListItem {
                PdfText $section -LinkBookmark $section.ToLower()
            }
        }
    }
    foreach ($section in $sections) {
        PdfPageBreak
        PdfBookmark $section.ToLower()
        PdfHeading $section
    }
}

$sales = @(
    [pscustomobject]@{ Region = 'North'; Q1 = 1.42; Q2 = 1.55; Q3 = 1.71 }
    [pscustomobject]@{ Region = 'South'; Q1 = 0.98; Q2 = 1.04; Q3 = 1.12 }
    [pscustomobject]@{ Region = 'East'; Q1 = 1.21; Q2 = 1.18; Q3 = 1.36 }
    [pscustomobject]@{ Region = 'West'; Q1 = 1.65; Q2 = 1.79; Q3 = 1.88 }
)
$dataPath = '.\Reports\Q3-Sales.json'
$sales | ConvertTo-Json | Set-Content -Path $dataPath
New-OfficePdf -Path .\Reports\Q3-Sales.pdf {
    PdfHeading 'Q3 sales'
    PdfTable -InputObject $sales
    PdfAttachment $dataPath -Name 'q3-sales.json' -MimeType 'application/json' -Relationship Source -Description 'Data used for the tables in this report.'
}

New-OfficePdf -Path .\Numbered.pdf {
    PdfFooter {
        PdfText 'Page '
        PdfPageNumber -IncludeTotal
    }
    PdfParagraph 'Body text.'
}

New-OfficePdf -Path .\Reports\Pricing-2027.pdf {
    PdfFooter -Alignment Right {
        PdfText 'Confidential - Northwind Traders - ' -Color TextMuted
        PdfPageNumber -IncludeTotal -Separator ' / ' -Bold
    }
    PdfHeading 'Pricing 2027'
}

New-OfficePdf -Path .\A4.pdf {
    PdfPageSetup -PageSize A4 -Margin 2.5cm
    PdfParagraph 'A4 page with 2.5 cm margins.'
}

$servers = Import-Csv -Path .\Data\Servers.csv
New-OfficePdf -Path .\Reports\Server-Inventory.pdf {
    PdfPageSetup -PageSize Letter -Orientation Landscape -Margin 0.5in -MarginLeft 1in
    PdfHeading 'Server inventory'
    PdfTable -InputObject $servers
}

New-OfficePdf -Path .\Reports\Quarterly-Ops.pdf {
    PdfHeader -Alignment Right {
        PdfImage .\Branding\Logo.png -Height 0.8cm
        PdfText ' Quarterly operations report' -Bold
    }
    PdfHeading 'Quarterly operations report'
}

New-OfficePdf -Path .\Footer.pdf {
    PdfFooter 'Page {page} of {pages}' -Alignment Center
    PdfParagraph 'Body text.'
}

New-OfficePdf -Path .\Handbooks\Employee-Handbook.pdf {
    PdfFooter -Alignment Right {
        PdfText 'Employee handbook - '
        PdfPageNumber
    }
    PdfFooter -Alignment Left -EvenPage {
        PdfPageNumber
        PdfText ' - Employee handbook'
    }
    PdfHeading 'Welcome'
}

New-OfficePdf -Path .\Letters\Welcome-Letter.pdf {
    PdfBackground -ImagePath .\Branding\Letterhead.png -Fit Cover -Opacity 0.15
    PdfParagraph 'Dear colleague,'
    PdfParagraph 'Welcome to Northwind Traders.'
}

New-OfficePdf -Path .\Plain.pdf -Theme Boardroom {
    PdfBackground -Clear -Target Shapes
    PdfHeading 'Plain variant'
}

New-OfficePdf -Path .\Reports\Customer-Survey.pdf {
    PdfBackgroundShape TopBand -Height 3cm -FillColor '#DBEAFE' -FillOpacity 0.75
    PdfBackgroundShape Ellipse -X 15cm -Y 23cm -Width 3.5cm -Height 2.5cm -FillColor '#99F6E4' -FillOpacity 0.35
    PdfHeading 'Customer survey 2026'
    PdfParagraph '1,248 responses from 14 countries.'
}

New-OfficePdf -Path .\Policies\Remote-Work-Policy-v3.pdf {
    PdfWatermark 'REVIEW COPY' -Size 64pt -Opacity 0.1 -Rotation -35 -Color TextMuted
    PdfHeading 'Remote work policy'
    PdfParagraph 'Version 3, for review by the works council.'
}

New-OfficePdf -Path .\Report.pdf {
    PdfMetadata -Title 'Service review' -Author 'IT Operations'
    PdfHeading 'Service review'
}

$services = @(
    [pscustomobject]@{ Service = 'Identity'; Owner = 'Platform'; Availability = 99.98; Incidents = 0; Status = 'Healthy' }
    [pscustomobject]@{ Service = 'Mail'; Owner = 'Messaging'; Availability = 99.71; Incidents = 2; Status = 'Watch' }
    [pscustomobject]@{ Service = 'File shares'; Owner = 'Infrastructure'; Availability = 99.95; Incidents = 1; Status = 'Healthy' }
    [pscustomobject]@{ Service = 'VPN'; Owner = 'Network'; Availability = 98.90; Incidents = 4; Status = 'At risk' }
)
New-OfficePdf -Path .\Reports\Accessible-Review.pdf {
    PdfCompliance PdfUa1 -Groundwork -Language 'en-US'
    PdfMetadata -Title 'Service review'
    PdfHeading 'Service review'
    PdfTable -InputObject $services
}
Get-OfficePdfCompliance -Path .\Reports\Accessible-Review.pdf -Profile PdfUa1

Add-OfficePdfStamp -Path .\Reports\Q3-Sales.pdf -OutputPath .\Reports\Q3-Sales-Labeled.pdf -Page '1,last' -Content {
    param($canvas, $page)
    PdfCanvasText -X 1.25cm -Y 1cm -Width 12cm {
        PdfText 'Owner: ' -Bold
        PdfText 'Sales operations' -Color Accent1
        PdfText " - page $($page.PageNumber) of $($page.PageCount)"
    }
}

Get-ChildItem -Path .\BoardPacks -Filter '*.pdf' | ForEach-Object {
    $extract = Join-Path -Path .\Extracts -ChildPath "$($_.BaseName)-Executive.pdf"
    Copy-OfficePdfPage -LiteralPath $_.FullName -OutputPath $extract -Page '1-2,last' -PassThru
} | ForEach-Object {
    Get-OfficeDocumentInfo -Path $_.FullName | Select-Object Path, PageCount
}

Get-ChildItem -Path .\Forms\Returned -Filter '*.pdf' | ForEach-Object {
    $fields = @{}
    Get-OfficePdfFormField -LiteralPath $_.FullName | ForEach-Object { $fields[$_.Name] = $_.Value }
    [pscustomobject]@{
        File        = $_.Name
        Requester   = $fields['Requester']
        System      = $fields['System']
        AccessLevel = $fields['AccessLevel']
        Approved    = $fields['Approved']
    }
} | Export-OfficeExcel -Path .\Forms\Access-Requests.xlsx

Import-Csv -Path .\HR\New-Hires.csv | ForEach-Object {
    $values = @{
        FullName   = $_.Name
        Department = $_.Department
        StartDate  = $_.StartDate
        Laptop     = $true
    }
    Set-OfficePdfFormField -Path .\HR\Onboarding-Form.pdf -OutputPath ".\HR\Onboarding\$($_.EmployeeId).pdf" -Value $values -Flatten
}

Get-ChildItem -Path .\Archive -Filter '*.pdf' | ForEach-Object {
    $file = $_
    Get-OfficePdfFont -LiteralPath $file.FullName -NeedsReview |
        Select-Object @{ Name = 'File'; Expression = { $file.Name } }, BaseFont, HasToUnicodeMap, HasEmbeddedFontFile
}

$null = New-Item -Path .\Archive\Optimized -ItemType Directory -Force
Get-ChildItem -Path .\Archive -Filter '*.pdf' | ForEach-Object {
    $output = Join-Path -Path .\Archive\Optimized -ChildPath $_.Name
    $null = Optimize-OfficePdf -LiteralPath $_.FullName -OutputPath $output -NoClobber
    [pscustomobject]@{
        File     = $_.Name
        BeforeKB = [math]::Round($_.Length / 1KB)
        AfterKB  = [math]::Round((Get-Item -LiteralPath $output).Length / 1KB)
    }
}

$ocr = New-OfficeOcrOptions -Language English, Polish
$null = New-Item -Path .\Scans\Searchable -ItemType Directory -Force
Get-ChildItem -Path .\Scans -Filter '*.pdf' | ForEach-Object {
    $output = Join-Path -Path .\Scans\Searchable -ChildPath $_.Name
    Update-OfficePdf -Path $_.FullName -OutputPath $output -Searchable -OcrOptions $ocr -PassThru
}

Get-ChildItem -Path .\Contracts -Filter '*-Signed.pdf' | ForEach-Object {
    $report = Get-OfficePdfSignature -LiteralPath $_.FullName
    if ($report.Findings) {
        [pscustomobject]@{ File = $_.Name; Findings = $report.Findings.Count }
    }
}

$ready = Get-ChildItem -Path .\Inbound -Filter '*.pdf' | Where-Object {
    $preflight = Get-OfficePdfDiagnostic -LiteralPath $_.FullName -Type Preflight
    -not $preflight.HasRewriteBlockers
}
$ready | Select-Object Name, Length
